def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                try:
                    prev_bids.append(float(bid))
                except Exception:
                    pass

    if not alive_opponents:
        return max(0.0, min(float(budget), 18.0))

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    base = 24.0 + 18.0 * scarcity

    if hp <= 2:
        base += 24.0
    elif hp <= 4:
        base += 10.0

    if no_water >= 2:
        base += 22.0
    elif no_water >= 1:
        base += 10.0

    base += min(urgent_opp * 2.0, 8.0)

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        target = max(avg_prev + 1.0, highest_prev + 1.5)
        if highest_prev >= 60:
            if hp > 4 and no_water == 0:
                base = min(base, 28.0 + 8.0 * scarcity)
            else:
                base = max(base, min(66.0, highest_prev + 1.0))
        else:
            base = max(base, target)

    if budget < DAILY_SALARY:
        base = min(base, max(12.0, budget * 0.55))

    if hp <= 2 or no_water >= 2:
        base = max(base, 60.0)

    bid = min(float(budget), base)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Alive opponents and their yesterday bids
    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    yesterday_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            try:
                yesterday_bids.append(float(bid))
            except Exception:
                pass

    # Base strategy: aim to win around our requirement but avoid unnecessary spending.
    # If supply is low, we bid more aggressively; if high, bid less.
    # target_bid is centered near a fraction of DAILY_SALARY.
    supply_mid = (MIN_SUPPLY + MAX_SUPPLY) / 2.0
    if supply <= supply_mid:
        target_bid = DAILY_SALARY * 0.62
    else:
        target_bid = DAILY_SALARY * 0.5

    # Reactive adjustment: if someone bid very high yesterday, slightly raise to avoid being outcompeted.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If we are in danger, match pressure more.
            if float(my_status.get('hp', 0)) <= 2.0:
                target_bid = max(target_bid, DAILY_SALARY * 0.9)
            else:
                target_bid = max(target_bid, DAILY_SALARY * 0.7)
        elif highest_prev_bid >= DAILY_SALARY * 0.65:
            target_bid = max(target_bid, highest_prev_bid * 0.92)
        else:
            # If opponents were mild, we can be slightly cheaper.
            target_bid = min(target_bid, DAILY_SALARY * 0.55)

    # Health/budget risk management
    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # If we've already missed water, increase bid to recover.
    if no_water_days >= 2:
        target_bid = max(target_bid, DAILY_SALARY * 0.75)
    if hp <= 2.0:
        target_bid = max(target_bid, DAILY_SALARY * 0.85)

    # Never bid more than we can afford.
    bid = min(budget, target_bid)

    # Ensure non-negative
    if bid < 0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    yesterday_bids = []
    yesterday_struggled_count = 0
    total_opponent_water_demand = 0

    for opp in alive_opponents:
        total_opponent_water_demand += opp['water_requirement']
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])
            if prev_trace.get('status') == 'no_water':
                yesterday_struggled_count += 1

    total_water_demand_all_agents = WATER_REQ + total_opponent_water_demand

    if my_hp <= 2:
        return min(my_budget, DAILY_SALARY * 0.95)

    if num_alive_opponents == 0:
        return min(my_budget, 1)

    if yesterday_bids:
        max_yesterday_bid = max(yesterday_bids)
        avg_yesterday_bid = sum(yesterday_bids) / len(yesterday_bids)

        if max_yesterday_bid >= DAILY_SALARY * 0.75 or \
           yesterday_struggled_count >= num_alive_opponents / 2 or \
           current_supply < total_water_demand_all_agents:

            if current_supply <= WATER_REQ + 2:
                return min(my_budget, DAILY_SALARY * 0.8)

            competitive_bid = max(max_yesterday_bid + 5, avg_yesterday_bid * 1.1)
            if my_hp < 4:
                competitive_bid = competitive_bid * 1.1

            return min(my_budget, competitive_bid, DAILY_SALARY * 0.9)

        else:
            if current_supply >= total_water_demand_all_agents:
                return min(my_budget, DAILY_SALARY * 0.25)
            else:
                moderate_bid = max(avg_yesterday_bid * 1.05, DAILY_SALARY * 0.35)
                return min(my_budget, moderate_bid)

    if current_supply >= total_water_demand_all_agents:
        return min(my_budget, DAILY_SALARY * 0.3)
    else:
        return min(my_budget, DAILY_SALARY * 0.6)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_agents = len(alive_opponents) + 1
    fair_share = supply / num_agents

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    if not yesterday_bids:
        return min(my_status['budget'], DAILY_SALARY * 0.5)

    max_prev = max(yesterday_bids)
    if fair_share < WATER_REQ:
        return min(my_status['budget'], max_prev + 5.0)

    return min(my_status['budget'], max(DAILY_SALARY * 0.3, max_prev * 0.9))

def get_bid(day_context, my_status, opponents_status):
